# Six-frame ORF scan (start codon ATG/GTG/TTG, stop TAA/TAG/TGA), min length 90 aa
def revcomp(s):
    return s.translate(str.maketrans('ACGT','TGCA'))[::-1]

genetic = {}
bases='TCAG'
aas='FFLLSSSSYY**CC*WLLLLPPPPHHQQRRRRIIIMTTTTNNKKSSRRVVVVAAAADDEEGGGG'
i=0
for b1 in bases:
    for b2 in bases:
        for b3 in bases:
            genetic[b1+b2+b3]=aas[i]; i+=1

def orfs(seqframe, frameno):
    res=[]
    starts=[]
    for i in range(0,len(seqframe)-2,3):
        codon=seqframe[i:i+3]
        if codon in ('ATG','GTG','TTG'):
            starts.append(i)
        if codon in ('TAA','TAG','TGA'):
            for st in starts:
                L=i-st
                if L>=270:   # >=90 codons incl stop
                    res.append((st, i+3, L//3))
            starts=[]
    return res

rc = revcomp(seq)
print("ORFs >= 90 codons (start-stop, aa incl. stop):")
for f in range(3):
    for label, s in [('+%d'%(f+1), seq[f:]), ('-%d'%(f+1), rc[f:])]:
        for st, sp, aa in orfs(s, label):
            if label.startswith('+'):
                a, b = f+st+1, f+sp
            else:
                a, b = len(seq)-(f+sp)+1, len(seq)-(f+st)
            print("  frame %-3s  nt %5d..%-5d  aa=%3d" % (label, a, b, aa))

